/**
 * Inline brand mark ("iC <···>"), vectorized from the original artwork.
 * Parts carry classes (mk-arc-top, mk-arc-bottom, mk-i, mk-i-dot, mk-lt, mk-gt, mk-dot) for CSS animation.
 */
function brand_mark(string $class = 'brand-mark'): string
{
    // Exact geometry fitted to the original logo: circles, ellipses and straight cuts (no tracing).
