/**
 * Wordmark "Integra Code" (Figtree 600 outlines fitted letter-by-letter to the original lettering). Requires brand_symbols() once per page.
 * Colors come from CSS: .wm-integra / .wm-code.
 */
function brand_wordmark(string $class = 'brand-wordmark'): string
{
    return '<svg class="' . $class . '" viewBox="21 815 1221 200" role="img" aria-label="Integra Code"><use href="#ic-wm-integra" class="wm-integra"/><use href="#ic-wm-code" class="wm-code"/></svg>';
}

